const body = $input.first().json.body;
const required = ['property_address', 'current_rent', 'currency', 'proposed_new_rent', 'lease_type'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const currentRent = parseFloat(body.current_rent);
const proposedRent = parseFloat(body.proposed_new_rent);
if (isNaN(currentRent) || isNaN(proposedRent)) return [{ json: { valid: false, error: 'rent amounts must be numbers' } }];
const leaseTypes = ['residential', 'commercial', 'retail', 'office', 'industrial', 'short_term'];
const leaseType = leaseTypes.includes(body.lease_type) ? body.lease_type : 'residential';
const increaseAmt = proposedRent - currentRent;
const increasePct = currentRent > 0 ? parseFloat((increaseAmt / currentRent * 100).toFixed(1)) : 0;
return [{ json: {
  valid: true,
  propertyAddress: body.property_address.trim(),
  propertyType: body.property_type || '',
  city: body.city || '',
  currentRent,
  proposedNewRent: proposedRent,
  increaseAmount: parseFloat(increaseAmt.toFixed(2)),
  increasePct,
  currency: body.currency,
  rentFrequency: body.rent_frequency || 'monthly',
  leaseType,
  tenantName: body.tenant_name || '',
  currentLeaseTerm: body.current_lease_term || '',
  leaseStartDate: body.lease_start_date || '',
  renewalDeadline: body.renewal_deadline || '',
  yearsAtProperty: parseFloat(body.years_at_property) || null,
  targetRent: parseFloat(body.target_rent) || null,
  marketDataProvided: (body.market_data || '').slice(0, 500),
  propertyIssues: (body.property_issues || '').slice(0, 600),
  tenantStrengths: (body.tenant_strengths || '').slice(0, 400),
  landlordContext: (body.landlord_context || '').slice(0, 400),
  negotiationStyle: body.negotiation_style || 'collaborative',
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

const search = $('Research Rental Market').first().json;
const input = $('Validate Input').first().json;
const marketContext = (search.results||[]).map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,350)}`).join('\n\n');
return [{ json: { input, marketContext: marketContext || 'No local market data found.' } }];

values.content:
Give lease renewal negotiation coaching.

Property: {{ $json.input.propertyAddress }}{{ $json.input.city ? ', ' + $json.input.city : '' }}
Property type: {{ $json.input.propertyType || 'not specified' }}
Lease type: {{ $json.input.leaseType }}

Current rent: {{ $json.input.currency }}{{ $json.input.currentRent }} {{ $json.input.rentFrequency }}
Proposed new rent: {{ $json.input.currency }}{{ $json.input.proposedNewRent }} {{ $json.input.rentFrequency }}
Increase: {{ $json.input.currency }}{{ $json.input.increaseAmount }} ({{ $json.input.increasePct }}%)
Target rent (if any): {{ $json.input.targetRent ? $json.input.currency + $json.input.targetRent : 'not specified' }}

Tenant name: {{ $json.input.tenantName || 'not provided' }}
Years at property: {{ $json.input.yearsAtProperty || 'not specified' }}
Current lease term: {{ $json.input.currentLeaseTerm || 'not specified' }}
Renewal deadline: {{ $json.input.renewalDeadline || 'not specified' }}

Property issues / maintenance backlog: {{ $json.input.propertyIssues || 'none noted' }}
Tenant strengths: {{ $json.input.tenantStrengths || 'none specified' }}
Landlord context: {{ $json.input.landlordContext || 'none provided' }}
Negotiation style: {{ $json.input.negotiationStyle }}
Market data provided: {{ $json.input.marketDataProvided || 'none' }}

Rental market research:
{{ $json.marketContext }}

Return this JSON:
{
  "increase_assessment": {
    "verdict": "one of: reasonable | above_market | significantly_above_market | needs_more_data",
    "market_context": "what the market data suggests about this increase",
    "typical_range": "typical renewal increase range for this area/type based on research"
  },
  "negotiation_strategy": {
    "recommended_counter": 0.0,
    "counter_rationale": "why this specific number — what it's based on",
    "fallback_position": 0.0,
    "walk_away_point": "at what rent level walking away makes more sense than renewing",
    "leverage_points": ["specific things in this tenant's situation that give negotiating power"],
    "weaknesses": ["factors that reduce negotiating leverage"]
  },
  "what_to_say": {
    "opening_approach": "how to open the negotiation — tone, channel (email/call/letter), timing",
    "email_subject": "subject line for the negotiation email",
    "email_body": "complete email to send to the landlord — professional, specific, uses the leverage points"
  },
  "if_landlord_pushes_back": [
    {
      "scenario": "likely landlord response",
      "response": "exactly what to say — specific words"
    }
  ],
  "beyond_rent": [
    {
      "item": "non-rent concession worth negotiating",
      "ask": "how to ask for it",
      "value": "approximate value or benefit"
    }
  ],
  "property_issues_as_leverage": "how to use any maintenance issues or deferred repairs in the negotiation — or null if none provided",
  "long_term_tenant_argument": "the specific case for why keeping this tenant is worth accepting a lower increase — written as talking points",
  "timing_advice": "when and how to respond — should they respond now or wait, what deadline to set",
  "one_thing_not_to_do": "the most common mistake tenants make in this type of lease negotiation"
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let coaching;
try { coaching = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
coaching._meta = {
  propertyAddress: input.propertyAddress,
  currentRent: input.currentRent,
  proposedNewRent: input.proposedNewRent,
  increaseAmount: input.increaseAmount,
  increasePct: input.increasePct,
  currency: input.currency,
  rentFrequency: input.rentFrequency,
  leaseType: input.leaseType,
  replyEmail: input.replyEmail
};
return [{ json: coaching }];

const c = $input.first().json;
const m = c._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const cur = m.currency;
const freq = m.rentFrequency;

const verdictConfig = {
  reasonable:               {color:'#16a34a', bg:'#f0fdf4', label:'Reasonable increase'},
  above_market:             {color:'#d97706', bg:'#fffbeb', label:'Above market'},
  significantly_above_market:{color:'#dc2626', bg:'#fef2f2', label:'Significantly above market'},
  needs_more_data:          {color:'#6b7280', bg:'#f9fafb', label:'Needs more data'}
};
const vc = verdictConfig[c.increase_assessment?.verdict] || verdictConfig.needs_more_data;
const ns = c.negotiation_strategy;

const pushbackCards = (c.if_landlord_pushes_back||[]).map(p => `
  <div style="border:1px solid #e5e7eb;border-radius:6px;margin-bottom:10px;overflow:hidden">
    <div style="background:#f9fafb;padding:8px 14px;font-size:13px;font-weight:600;color:#374151">Landlord: "${esc(p.scenario)}"</div>
    <div style="padding:10px 14px;font-size:14px;color:#1e40af;font-style:italic;line-height:1.6">You: "${esc(p.response)}"</div>
  </div>`).join('');

const beyondRent = (c.beyond_rent||[]).map(b => `
  <div style="padding:9px 0;border-bottom:1px solid #f3f4f6">
    <div style="font-size:14px;font-weight:600">${esc(b.item)}</div>
    <div style="font-size:13px;color:#2563eb;margin-top:2px">${esc(b.ask)}</div>
    ${b.value ? `<div style="font-size:12px;color:#9ca3af;margin-top:1px">${esc(b.value)}</div>` : ''}
  </div>`).join('');

const leverageList = (ns?.leverage_points||[]).map(l => `<li style="font-size:13px;margin-bottom:5px;color:#166534">${esc(l)}</li>`).join('');
const weaknessList = (ns?.weaknesses||[]).map(w => `<li style="font-size:13px;margin-bottom:5px;color:#7f1d1d">${esc(w)}</li>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f5f0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:680px;margin:0 auto">
  <div style="background:#1c1917;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#78716c;margin-bottom:5px">Lease Renewal Coach · ${esc(m.leaseType)}</div>
    <div style="font-size:18px;font-weight:700">${esc(m.propertyAddress)}</div>
    <div style="font-size:14px;color:#a8a29e;margin-top:3px">${cur}${m.currentRent} → ${cur}${m.proposedNewRent} ${freq} (+${m.increasePct}%)</div>
  </div>

  <div style="background:${vc.bg};padding:14px 28px;border:1px solid ${vc.color}44;border-top:none">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:12px">
      <div>
        <span style="background:${vc.color};color:#fff;font-size:12px;font-weight:700;padding:3px 10px;border-radius:12px">${vc.label}</span>
        <div style="font-size:13px;color:#555;margin-top:6px;line-height:1.5">${esc(c.increase_assessment?.market_context)}</div>
        <div style="font-size:12px;color:#9ca3af;margin-top:3px">Typical range: ${esc(c.increase_assessment?.typical_range||'see market data')}</div>
      </div>
      ${ns?.recommended_counter ? `<div style="text-align:right">
        <div style="font-size:11px;color:#9ca3af;text-transform:uppercase;letter-spacing:0.4px">Counter ask</div>
        <div style="font-size:26px;font-weight:800;color:#1a1a1a">${cur}${ns.recommended_counter.toLocaleString()}</div>
        <div style="font-size:12px;color:#6b7280">Fallback: ${cur}${(ns.fallback_position||0).toLocaleString()}</div>
      </div>` : ''}
    </div>
  </div>

  ${ns ? `<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Strategy</div>
    <p style="font-size:14px;line-height:1.65;color:#374151;margin:0 0 10px">${esc(ns.counter_rationale)}</p>
    ${ns.walk_away_point ? `<div style="font-size:13px;color:#dc2626;background:#fef2f2;padding:8px 12px;border-radius:4px">Walk away if: ${esc(ns.walk_away_point)}</div>` : ''}
  </div>` : ''}

  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px">
      ${leverageList ? `<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:7px">Your leverage</div><ul style="padding-left:16px;margin:0">${leverageList}</ul></div>` : ''}
      ${weaknessList ? `<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:7px">Watch out for</div><ul style="padding-left:16px;margin:0">${weaknessList}</ul></div>` : ''}
    </div>
  </div>

  <div style="background:#eff6ff;padding:16px 28px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:5px">Opening approach</div>
    <div style="font-size:14px;color:#1e3a8a;line-height:1.65;margin-bottom:10px">${esc(c.what_to_say?.opening_approach)}</div>
    ${c.what_to_say?.email_subject ? `<div style="font-size:12px;color:#3b82f6;margin-bottom:4px"><strong>Subject:</strong> ${esc(c.what_to_say.email_subject)}</div>` : ''}
    ${c.what_to_say?.email_body ? `<div style="background:#fff;border:1px solid #bfdbfe;border-radius:6px;padding:14px;font-size:14px;line-height:1.75;white-space:pre-wrap;color:#374151">${esc(c.what_to_say.email_body)}</div>` : ''}
  </div>

  ${pushbackCards ? `<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">When they push back</div>
    ${pushbackCards}
  </div>` : ''}

  ${c.long_term_tenant_argument ? `<div style="background:#f0fdf4;padding:14px 28px;border:1px solid #bbf7d0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:6px">Your case as a long-term tenant</div>
    <div style="font-size:14px;color:#166534;line-height:1.65">${esc(c.long_term_tenant_argument)}</div>
  </div>` : ''}

  ${c.property_issues_as_leverage ? `<div style="background:#fffbeb;padding:14px 28px;border:1px solid #fde68a">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:6px">Property issues as leverage</div>
    <div style="font-size:14px;color:#78350f;line-height:1.65">${esc(c.property_issues_as_leverage)}</div>
  </div>` : ''}

  ${beyondRent ? `<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">If rent is stuck — negotiate these</div>
    ${beyondRent}
  </div>` : ''}

  <div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Timing</div>
    <div style="font-size:14px;color:#374151;line-height:1.6">${esc(c.timing_advice)}</div>
  </div>

  ${c.one_thing_not_to_do ? `<div style="background:#fef2f2;padding:12px 28px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:4px">Don't do this</div>
    <div style="font-size:14px;color:#7f1d1d;line-height:1.6">${esc(c.one_thing_not_to_do)}</div>
  </div>` : ''}

  <div style="background:#1c1917;color:#57534e;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Lease Renewal Coach · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, propertyAddress: m.propertyAddress, increasePct: m.increasePct, counterRent: ns?.recommended_counter || null, currency: cur, coaching: c } }];
